  ui_story_30930601_55_dialog_content = "¿Pero pensé que estábamos en la puerta de tu salón?",
  ui_story_30930601_56_dialog_content = "¿Podría ser esa puerta ... en realidad era un portal?",
  ui_story_30930601_57_dialog_content = "¿Uno que le permita atravesar el tiempo y el espacio?",
  ui_story_30930601_58_dialog_content = "¿Qué pasa? ¿No te gusta mi habitación?",
  ui_story_30930601_59_dialog_content = "¡Es muy única! ¡Pacífica y misteriosa!",
  ui_story_30930601_60_dialog_content = "Por supuesto, la sala del jefe tendría un fondo detallado como este ...",
  ui_story_30930601_61_dialog_content = "Parece que últimamente has pasado mucho tiempo con Gronru.",
  ui_story_30930601_62_dialog_content = "Incluso has captado algunos de sus patrones de habla.",
  ui_story_30930601_63_dialog_content = "Jejeje ... Este tipo de compatibilidad ... Oh, es difícil de resistir.",
  ui_story_30930601_64_dialog_content = "T-tú ... yo ... uh ...",
  ui_story_30930601_65_dialog_content = "Incluso te pareces a ella cuando te da vergüenza ...",
  ui_story_30930601_66_dialog_content = "Este tipo de tensión y excitación puede provocar una fuerte respuesta nerviosa.",
  ui_story_30930601_67_dialog_content = "Hace que los latidos de su corazón se aceleren y sus vasos sanguíneos se expandan, lo que finalmente resulta en una cara sonrojada.",
  ui_story_30930601_68_dialog_content = "Y en ciertos casos, sudoración incontrolable.",
  ui_story_30930601_69_dialog_content = "*Sorber*",
  ui_story_30930601_70_dialog_content = "... Estás siendo raro, ¿lo sabías?",
  ui_story_30930601_71_dialog_content = "De todos modos, ¿son estos ... especímenes biológicos?",
  ui_story_30930601_72_dialog_content = "Libros y materiales por todo el suelo, y todavía estás usando tu bata de laboratorio.",
  ui_story_30930601_73_dialog_content = "¿Estás trabajando ahora mismo? Si mal no recuerdo, se supone que hoy es tu día libre.",
  ui_story_30930601_74_dialog_content = "Una persona puede tomar descansos de su trabajo, pero la carrera requiere la atención y el tiempo completo de la persona.",
  ui_story_30930601_75_dialog_content = "Incluso cuando están fuera del reloj ...",
  ui_story_30930601_76_dialog_content = "Un entorno confortable puede mejorar la productividad en algunos casos.",
  ui_story_30930601_77_dialog_content = "Bueno, no quisiera perturbar tu trabajo ...",
  ui_story_30930601_78_dialog_content = "De hecho, estoy muy agradecido por la interrupción. Por así decirlo, me he encontrado con un bloqueo en mi investigación.",
  ui_story_30930601_79_dialog_content = "Todos mis experimentos anteriores habían fallado, pero afortunadamente Gronru pudo encontrar <color=#FFB400>esta botella de solvente</color> para mí.",
  ui_story_30930601_80_dialog_content = "Oh ... Entonces, ¿para qué es?",
  ui_story_30930601_81_dialog_content = "Se usa en separación y purificación.",
  ui_story_30930601_82_dialog_content = "En pocas palabras, estoy tratando de separar algo de un cristal mediante el calentamiento y el uso de este solvente.",
  ui_story_30930601_83_dialog_content = "A través de la diferencia de solubilidad de varios compuestos sólidos en soluciones ...",
  ui_story_30930601_84_dialog_content = "Er ... Pareces un poco perdido.",
  ui_story_30930601_85_dialog_content = "Digamos, por ejemplo, que tú y Barton entran en un sauna al mismo tiempo.",
  ui_story_30930601_86_dialog_content = "Con su piel gruesa, puede soportar el calor del sauna durante 30 minutos sin derretirse.",
  ui_story_30930601_87_dialog_content = "Tú, por otro lado, solo durarías 3 minutos antes de convertirte en un charco.",
  ui_story_30930601_88_dialog_content = "Como tal, podría sacar a un Barton entero del sauna sin ti.",
  ui_story_30930601_89_dialog_content = "¡¿Dices que me dejarías arder en el sauna, entonces?!",
  ui_story_30930601_90_dialog_content = "Sin embargo, este método tiene sus limitaciones, especialmente cuando se parte de cero.",
  ui_story_30930601_91_dialog_content = "Elegir el solvente correcto es crucial, uno que no reaccione con el objeto purificado que estoy tratando de recuperar. Aquí es donde radica la dificultad.",
  ui_story_30930601_92_dialog_content = "Por ejemplo, debido a su incompatibilidad, un estilo de vida antiguo e idílico sería un \"solvente\" que no reaccionó con Barton.",
  ui_story_30930601_93_dialog_content = "En mis exámenes preliminares, eliminé una gran cantidad de posibles solventes.",
  ui_story_30930601_94_dialog_content = "¿Debería darte otra comparación de cómo fue el proceso de selección?",
  ui_story_30930601_95_dialog_content = "Fue como...",
  ui_story_30930601_96_dialog_content = "<color=#e8d9bb>Y así, Migard pasó aproximadamente una hora dando a PlayerName una explicación abreviada de su trabajo.</color>",
  ui_story_30930601_97_dialog_content = "(Mi cabeza está llena de las extrañas comparaciones de Migard ... siento que esto no tiene nada que ver con la ciencia.)",
  ui_story_30930601_98_dialog_content = "(Aun así, al ver la cara de Migard tan llena de emoción ... puedo decir que está realmente apasionada por esto.)",
  ui_story_30930601_99_dialog_content = "De todos modos, después de que todo esté dicho y hecho, es hora de realizar el experimento ahora, ¿verdad?",
  ui_story_30930601_100_dialog_content = "Correcto.",
  ui_story_30930601_101_dialog_content = "En ese caso, no te molestaré más ...",
  ui_story_30930601_102_dialog_content = "Después de todo, tener a alguien como yo cerca solo se interpondría en tu camino.",
  ui_story_30930601_103_dialog_content = "Me voy ahora, ¡pero estoy seguro de que tu experimento será un éxito, Migard!",
  ui_story_30930601_104_dialog_content = "Tienes un punto.",
  ui_story_30930601_105_dialog_content = "Te daré la noticia más tarde, PlayerName.",
  ui_story_30930601_106_dialog_content = "(Pero después de eso, pasaron varios días antes de volver a ver a Migard.)",
  ui_story_30930601_107_dialog_content = "Entonces, ¿tienes alguna palabra sobre Migard o cómo está?",
  ui_story_30930601_108_dialog_content = "No, realmente no. Todo lo que sé es que no ha salido de su salón en días.",
  ui_story_30930601_109_dialog_content = "Parece que la jefa perdió su mecanismo de itinerancia, ¿eh?",
  ui_story_30930601_110_dialog_content = "Hablando de eso, ¡encontré un nuevo juego para jugar recientemente!",
  ui_story_30930601_111_dialog_content = "¿Qué dices, PlayerName? ¿Quieres jugar algunos partidos?",
  ui_story_30930601_112_dialog_content = "Hoy no, Gronru. Debería ir a ver cómo está.",
  ui_story_30930601_113_dialog_content = "Ya no tienes miedo de enfrentarte a ella por tu cuenta, ¿eh, PlayerName? ¡Realmente has subido de nivel!",
  ui_story_30930601_114_dialog_content = "(Oh...)",
  ui_story_30930601_115_dialog_content = "(Todavía da demasiado miedo. Quizás debería retirarme por ahora ...)",
  ui_story_30930601_116_dialog_content = "(Lentamente ... Tranquilamente ...)",
  ui_story_30930601_117_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_30930601_118_dialog_content = "¡¿Una explosión?!",
  ui_story_30930601_119_dialog_content = "¡Migard! ¡¿Estás bien?!",
  ui_story_30930601_120_dialog_content = "¡Migard!",
  ui_story_30930601_121_dialog_content = "<color=#e8d9bb>Desmenuzar ...</color>",
  ui_story_30930601_122_dialog_content = "Oh ... eres tú, PlayerName.",
  ui_story_30930601_123_dialog_content = "Esa explosión de ahora ...",
  ui_story_30930601_124_dialog_content = "Fue un pequeño efecto secundario del experimento, eso es todo.",
  ui_story_30930601_125_dialog_content = "Mientras estés bien ... No te hemos visto en días, Migard.Estaba empezando a preocuparme.",
  ui_story_30930601_126_dialog_content = "¿Se armó de valor para venir a verme, aunque tenía tanto miedo?",
  ui_story_30930601_127_dialog_content = "Incluso llegaste a mi salón ... ¿Preocupado por mi seguridad?",
  ui_story_30930601_128_dialog_content = "PlayerName ... Eres demasiado adorable, siento que no puedo evitarlo ...",
  ui_story_30930601_129_dialog_content = "Pero ahora que miro la hora, supongo que estoy atrasado para tomar un poco de aire fresco.",
  ui_story_30930601_130_dialog_content = "¿Has terminado tu experimento?",
  ui_story_30930601_131_dialog_content = "Sí... a pesar del tiempo que me llevó, finalmente logré un resultado satisfactorio.",
  ui_story_30930601_132_dialog_content = "Pareces mucho más relajado ... ¿Salió bien el experimento, entonces?",
  ui_story_30930601_133_dialog_content = "Supongo.",
  ui_story_30930601_134_dialog_content = "Después de todo, estamos hablando de ti. Ningún experimento tiene oportunidad contra ti y tus Espinas de Buceo, Migard.",
  ui_story_30930601_135_dialog_content = "También invirtió todo este tiempo y esfuerzo en ello.",
  ui_story_30930601_136_dialog_content = "No, PlayerName. El experimento fue un completo y absoluto fracaso.",
  ui_story_30930601_137_dialog_content = "Al final, todavía existía una gran cantidad de impurezas dentro del cristal.",
  ui_story_30930601_138_dialog_content = "¿Ah?",
  ui_story_30930601_139_dialog_content = "Simplemente había demasiadas variables y factores para tener en cuenta.",
  ui_story_30930601_140_dialog_content = "Es como si de repente hubiéramos descubierto que Barton podía soportar estar sentado en una sauna a 100°C.",
  ui_story_30930601_141_dialog_content = "Quizás se debió a su indomable fuerza de voluntad.",
  ui_story_30930601_142_dialog_content = "O tal vez simplemente había hecho una apuesta con Wrath y decidió que no podía permitirse perder.",
  ui_story_30930601_143_dialog_content = "O tal vez ya había modificado todo su cuerpo en un arma de guerra fabricada en acero.",
  ui_story_30930601_144_dialog_content = "Tal vez, podamos saltarnos la parte sobre Barton y saunas ...",
  ui_story_30930601_145_dialog_content = "Entonces...",
  ui_story_30930601_146_dialog_content = "No parezcas tan nervioso. Estoy perfectamente bien, o mejor dicho, tengo el ánimo bastante alto.",
  ui_story_30930601_147_dialog_content = "¿Estás de buen humor incluso después de que tu experimento falló?",
  ui_story_30930601_148_dialog_content = "No crees que lograr el éxito en un experimento sea tan fácil, ¿verdad, PlayerName?",
  ui_story_30930601_149_dialog_content = "Es difícil de decir, ya que todo lo que he visto de ustedes son proyectos exitosos.",
  ui_story_30930601_150_dialog_content = "Estás en lo correcto. Esos experimentos exitosos eclipsaron los fracasos, encubrieron todo.",
  ui_story_30930601_151_dialog_content = "Incluso el más pequeño de los éxitos descansa sobre una montaña de mil fracasos.",
  ui_story_30930601_152_dialog_content = "El éxito no es fácil de lograr, especialmente cuando se trata de ciencia. De hecho, suele ser accidental y siempre minoritario cuando se trata de resultados.",
  ui_story_30930601_153_dialog_content = "Incluso el éxito de mis Espinas de Buceo fue una cuestión de pura coincidencia.",
  ui_story_30930601_154_dialog_content = "Y en muchos casos, los investigadores pasan toda su vida en pos de un puñado de resultados exitosos.",
  ui_story_30930601_155_dialog_content = "Pero al final, todo el éxito fue solo empujar nuestras barreras cognitivas un pequeño paso más hacia la inmensidad del universo.",
  ui_story_30930601_156_dialog_content = "Cuando lo pones de esa manera, parece que la ciencia no está llena más que de obstáculos ...",
  ui_story_30930601_157_dialog_content = "Pero ahí radica el placer de la investigación.",
  ui_story_30930601_158_dialog_content = "Nunca he tenido miedo al fracaso. Después de todo, refutar ideas es una parte integral de la investigación.",
  ui_story_30930601_159_dialog_content = "De todos modos, gracias, PlayerName.",
  ui_story_30930601_160_dialog_content = "Tu preocupación es más que suficiente para darme fuerzas para seguir adelante.",
  ui_story_30930601_161_dialog_content = "Migard...",
  ui_story_30930601_162_dialog_content = "Aun así, sigo siendo un biólogo talentoso.",
  ui_story_30930601_163_dialog_content = "Empezar un proyecto experimental conmigo significa mayores posibilidades de éxito que con otros.",
  ui_story_30930601_164_dialog_content = "Es por eso...",
  ui_story_30930601_165_dialog_content = "Mi próximo experimento será sondear la estructura de la mente y el cerebro del jugador común.",
  ui_story_30930601_166_dialog_content = "Y mi asistente para este experimento ... ¡no serás otro que tú, PlayerName!",
  ui_story_30930601_167_option_content = "Nop.",
  ui_story_30930601_168_option_content = "De ninguna manera.",
  ui_story_30930601_169_option_content = "Absolutamente no.",
  ui_story_30930601_170_dialog_content = "¿Rechazarme tan rápido, hmm ...?",
  ui_story_30930601_171_dialog_content = "(¿Por qué siente que ella no va a aceptar un no por respuesta ...?)",
  ui_story_30930601_172_dialog_content = "(Y esa mirada en sus ojos ... ¡¡Es incluso más espeluznante de lo habitual!!)",
  ui_story_30930601_173_dialog_content = "Si no puedo tener a Gronru como sujeto de prueba, lo mejor sería alguien que haya sido profundamente influenciado por ella. Alguien como tú, PlayerName ...",
  ui_story_30930601_174_dialog_content = "¡Ah, qué maravilloso golpe de suerte que los materiales de mi experimento hayan llegado a mi puerta tan temprano esta mañana!",
  ui_story_30930601_175_dialog_content = "Ahora, suave y cuidadosamente ... abre la cabeza de PlayerName y mira qué hay dentro.",
  ui_story_30930601_176_dialog_content = "¡Dije que no quiero participar en esto!",
